// Addresses and constants of the sniper-tax program. They mirror `crates/sniper-tax-client`
// and `crates/sniper-tax-math`; `test/vectors.json`, generated by the Rust client, pins them.

import { address, type Address } from '@solana/kit';

/** The program's address on devnet. Deploying elsewhere changes it here too. */
export const PROGRAM_ID: Address = address('EZwLuZ8mSiBoeKtbHwQK4kxCqqj4JuureT1kHpTK3i6b');

/** Wrapped SOL, the usual quote mint. */
export const NATIVE_MINT: Address = address('So11111111111111111111111111111111111111112');

/** Mint indices in a pool's `MarketInfo`. */
export const TOKEN_INDEX = 0;
export const QUOTE_INDEX = 1;

/** The most SOL a pool's setup may borrow from whoever calls `create_market`. */
export const MAX_SETUP_LAMPORTS = 100_000_000n;

export const POOL_SEED = new TextEncoder().encode('launch');
export const CONFIG_SEED = new TextEncoder().encode('config');

/** Bounds every tax schedule must meet (`TaxSchedule::validate`). */
export const MAX_START_BPS = 9_900;
export const MAX_END_BPS = 500;
export const MIN_DURATION_SECS = 60;
export const MAX_DURATION_SECS = 1_800;
export const BPS = 10_000;

/**
 * Hard caps on the protocol's fees, enforced by the program whatever the config's admin sets.
 * The config's current values are lower (10% and 0.01 SOL on devnet); read them with
 * `decodeProtocolConfig`. A pool records both at `create_market`: its share of the tax never
 * changes after that, and its launch fee can only go down (`launch_fee_due`).
 */
export const MAX_PROTOCOL_TAX_SHARE_BPS = 2_000;
export const MAX_LAUNCH_FEE_LAMPORTS = 50_000_000n;

/** Anchor discriminators: the first 8 bytes of sha256("global:<name>") or ("account:<Name>"). */
export const INSTRUCTION_DISCRIMINATORS = {
    launch: new Uint8Array([153, 241, 93, 225, 22, 69, 74, 61]),
    claimTax: new Uint8Array([109, 18, 115, 217, 37, 74, 110, 30]),
    sweepProtocolFees: new Uint8Array([117, 225, 240, 75, 71, 195, 44, 43]),
    pipelineQuote: new Uint8Array([134, 139, 91, 59, 182, 37, 152, 218]),
} as const;

export const ACCOUNT_DISCRIMINATORS = {
    LaunchPool: new Uint8Array([29, 65, 189, 216, 67, 129, 179, 61]),
    ProtocolConfig: new Uint8Array([207, 91, 250, 28, 152, 179, 215, 209]),
} as const;
